  ('tpl_expiry_1d', 'expiry_1d', 'en', 'utility', 'Hi {{name}}, your {{plan}} membership expires tomorrow ({{date}}). Reply here to renew.', '["name","plan","date"]'),
  ('tpl_payment_due', 'payment_due', 'en', 'utility', 'Hi {{name}}, a payment of {{amount}} is due for your {{plan}} membership. Reply here if you have already paid.', '["name","amount","plan"]'),
  ('tpl_welcome', 'welcome', 'en', 'utility', 'Welcome to PULSE GYM, {{name}}! Your membership code is {{code}}.', '["name","code"]');

